def parse_duration(s):
    import re
    h_m_s = re.findall(r'(\d+)(h|m|s)?', s)
    total_seconds = 0
    for h, m, s in h_m_s:
        if h:
            total_seconds += int(h) * 3600
        if m:
            total_seconds += int(m) * 60
        if s:
            total_seconds += int(s)
    return total_seconds
```

